def min_coins(coins, amount, change):
    # Initialize a list to store the minimum coins used
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: no coins needed for amount 0

    # Iterate through each coin
    for coin in coins:
        for value in range(coin, amount + 1):
            if dp[value - coin] + 1 < dp[value]:
                dp[value] = dp[value - coin] + 1

    # If the maximum value in the dp list is greater than the change, return -1
    return dp[change] if dp[change] <= change else -1

