def rgb_to_hsv(r, g, b):
    # Calculate the brightness
    brightness = (r + g + b) / 3

    # Determine the saturation
    if r == g == b:
        saturation = 0
    else:
        saturation = (r - g - b) / (3 - max(r, g, b))

    # Determine the hue
    if r == g == b:
        hue = 0
    elif r > g and r > b:
        hue = (60 * (g - b)) / (3 - max(r, g, b))
    elif g > r and g > b:
        hue = (60 * (b - r)) / (3 - max(r, g, b))
    elif b > r and b > g:
        hue = (60 * (r - g)) / (3 - max(r, g, b))

    # Convert to HSV tuple
    hsv = (brightness, saturation, hue)
    return hsv

