def rgb_to_hsv(r, g, b):
    # Convert RGB to HSL
    h = 0
    s = 1.0
    v = 1.0
    if r == 0 and g == 0 and b == 0:
        return h, s, v
    max_val = max(r, g, b)
    min_val = min(r, g, b)
    if max_val == min_val:
        h = 0
    else:
        h = (max_val - min_val) / max_val * 60
    if max_val == 0 or min_val == 0:
        s = 0.0
    else:
        s = (max_val - min_val) / (max_val - min_val) * 100.0
    v = max_val
    return h, s, v

