def subset(nums, n):
    # Initialize a list to store the count of each element
    dp = [0] * (1 << n)

    # Base case: if there are 0 elements, the minimum number of subsets is 0
    dp[0] = 1

    # Iterate through each element and each possible combination of its subset
    for i in range(1, n):
        for j in range(1 << n):
            if (j & (1 << i)) == 0:
                dp[j] += dp[j ^ (1 << i)]

    # The minimum number of subsets is the last element in the dp list
    return dp[-1]

def subset(nums, n):
