def subset(nums, n):
    # Initialize the dp array to store the number of subsets for each length
    dp = [[0 for _ in range(n+1)] for _ in range(n+1)]

    # Base case: If we have 0 or 1 elements, we have one subset (empty set or containing only one element)
    for i in range(1, n+1):
        dp[i][0] = 1
        dp[i][1] = 1

    # Fill the dp array
    for i in range(2, n+1):
        for j in range(2, i+1):
            if nums[j-1] == nums[i-1]:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j]

    # Return the number of subsets with distinct elements
    return dp[n][n]

